# Generates glshim.c: every GLES 3.0 entry point in gl3.h, resolved lazily
# through SDL_GL_GetProcAddress (Windows has no system libGLESv2).
import os
import re

here = os.path.dirname(os.path.abspath(__file__))
header = open(os.path.join(here, '..', 'gles', 'GLES3', 'gl3.h')).read()
protos = re.findall(r'GL_APICALL\s+(.+?)\s*GL_APIENTRY\s+(gl\w+)\s*\((.*?)\);', header)
out = ['// Generated by gen.py: resolves GLES3 entry points through SDL_GL_GetProcAddress.',
       '#include <GLES3/gl3.h>', '#include <SDL3/SDL_video.h>', '']
for ret, name, args in protos:
    params = [a.strip() for a in args.split(',')] if args.strip() != 'void' else []
    names = [re.findall(r'(\w+)\s*(?:\[\])?$', p)[0] for p in params]
    call = ', '.join(names)
    result = '' if ret == 'void' else 'return '
    out.append(f'GL_APICALL {ret} GL_APIENTRY {name}({args}) {{\n'
               f'    typedef {ret} (GL_APIENTRY *fn_t)({args});\n'
               f'    static fn_t fn;\n'
               f'    if (!fn) fn = (fn_t)SDL_GL_GetProcAddress("{name}");\n'
               f'    {result}fn({call});\n}}\n')
open(os.path.join(here, 'glshim.c'), 'w').write('\n'.join(out))
print(len(protos), 'functions')
